import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int count = in.nextInt();
        int largest = in.nextInt();
        for (int i = 1; i < count; i++) {
            int next = in.nextInt();
            if (next > largest) {
                largest = next;
            }
        }
        System.out.println("Largest: " + largest);
    }
}
